def transform(grid):
    g = np.array(grid)
    bg = background(g)
    h, w = g.shape
    cy, cx = h // 2, w // 2
    ys, xs = np.indices(g.shape)
    dist = np.maximum(np.abs(ys - cy), np.abs(xs - cx))
    ring_colour = {}
    for y in range(h):
        for x in range(w):
            if g[y, x] != bg:
                ring_colour[int(dist[y, x])] = int(g[y, x])
    out = g.copy()
    for d in sorted(ring_colour, reverse=True):
        out[dist == d] = ring_colour[d]
        emit(out, f"Dot of colour {ring_colour[d]} lies at distance {d} from the centre, so paint the whole ring at distance {d} with it.")
    emit(out, "All rings painted: final concentric squares.")
    return out
